private void copyChildren(String table, String key, String columns, long to, long from) {
    jdbc.update("INSERT INTO " + table + " (" + key + ", " + columns + ") SELECT ?, " + columns + " FROM " + table
            + " WHERE " + key + " = ?" + (hasId(table) ? " ORDER BY id" : ""), to, from);
}

